CREATE DATABASE IF NOT EXISTS lostfound CHARACTER SET utf8mb4;
USE lostfound;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) UNIQUE NOT NULL, full_name VARCHAR(100) NOT NULL, email VARCHAR(120), course VARCHAR(80), password_hash VARCHAR(255) NOT NULL, role ENUM('admin','student','viewer') NOT NULL DEFAULT 'student', active TINYINT(1) NOT NULL DEFAULT 1, failed INT NOT NULL DEFAULT 0, locked_until DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) UNIQUE NOT NULL);
CREATE TABLE items(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, category_id INT NOT NULL, name VARCHAR(100) NOT NULL, description TEXT NOT NULL, location VARCHAR(120) NOT NULL, event_date DATE NOT NULL, photo VARCHAR(60) NULL, status ENUM('Lost','Found','Claimed','Returned') NOT NULL, verified TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), INDEX(status), INDEX(verified));
CREATE TABLE claims(id INT AUTO_INCREMENT PRIMARY KEY, item_id INT NOT NULL, user_id INT NOT NULL, proof TEXT NOT NULL, status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending', remarks VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(40) NOT NULL, details VARCHAR(255), ip VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
